import { mdiAccountPlus, mdiCog, mdiDiceMultiple, mdiEye, mdiEyeOff } from '@mdi/js';
import { LitElement, TemplateResult, css, html, nothing } from 'lit';
import { property, state } from 'lit/decorators.js';

import { CONDITION_DOMAINS, ensureEntityPickerLoaded, isConditionEntity } from './ha-components';
import { HomeAssistant } from './ha_type_stubs';
import { lcmCssVars, lcmDialogActionStyles, lcmRevealButtonStyles } from './shared-styles';
import { LockCodeManagerAddUserCardConfig } from './types';

/** What `generate_pin` accepts, and what it defaults to. */
const MIN_PIN_LENGTH = 4;
const MAX_PIN_LENGTH = 12;
const DEFAULT_PIN_LENGTH = 4;

/**
 * The button that adds a user to a Lock Code Manager config entry.
 *
 * Deliberately holds no state about the entry it belongs to: it collects a
 * name and an optional PIN, hands them to the `add_user` action, and
 * reloads. Allocation, capacity and slot numbering are the integration's
 * business, and asking the card to preview any of that would mean teaching
 * it rules that already live in one place.
 */
export class LockCodeManagerAddUserCard extends LitElement {
    static styles = [
        lcmCssVars,
        lcmDialogActionStyles,
        lcmRevealButtonStyles,
        css`
            ha-card {
                align-items: center;
                cursor: pointer;
                display: flex;
                gap: 12px;
                justify-content: center;
                padding: 20px 16px;
            }

            ha-card:hover {
                background: var(--lcm-section-bg-hover);
----
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        this._open();
                    }
                }}
            >
                <ha-svg-icon .path=${mdiAccountPlus}></ha-svg-icon>
                <span class="label">Add user</span>
            </ha-card>
            <button class="manage" @click=${this._manage}>
                <ha-svg-icon .path=${mdiCog}></ha-svg-icon>
                <span>Manage users in settings</span>
            </button>
            ${this._showDialog ? this._renderDialog() : nothing}
        `;
    }

    /** Seam so a test can observe the reload without navigating the runner. */
    protected _reload(): void {
        window.location.reload();
    }

    /**
     * Go to the entry's own page, where Home Assistant lists each user and
     * offers its edit and delete dialogs.
     *
     * Navigation rather than opening that dialog here: Home Assistant's flow
     * dialog ships in a lazily-loaded chunk a Lovelace view has no reason to
     * have pulled in, and an unregistered custom element renders as nothing
     * rather than failing. There is no URL that starts a subentry flow, so
     * the page that hosts it is as close as a card can get.
     */
    private _manage(): void {
        const anchor = this._config.config_entry_id
            ? `#config_entry=${this._config.config_entry_id}`
            : '';
        history.pushState(null, '', `/config/integrations/integration/lock_code_manager${anchor}`);
        window.dispatchEvent(new CustomEvent('location-changed'));
    }

    private _open(): void {
        this._name = '';
        this._pin = '';
        this._condition = '';
        this._pinVisible = false;
        this._pinLength = DEFAULT_PIN_LENGTH;
        this._enabled = true;
        this._error = undefined;
        this._showDialog = true;
    }

    private _close(): void {
        this._showDialog = false;
    }

    private _renderDialog(): TemplateResult {
        return html`
            <ha-dialog open @closed=${this._close} .heading=${'Add user'}>
                <div class="dialog-content">
                    <p class="dialog-description">
                        A slot is picked for you on every lock in this entry. Leave the PIN blank to
                        set one later.
                    </p>
                    <div class="field">
                        <label class="field-label" for="add-user-name">Name</label>
                        <div class="field-control">
                            <input
                                id="add-user-name"
                                class="field-input"
                                type="text"
                                required
                                .value=${this._name}
                                @input=${(e: Event) => {
                                    this._name = (e.target as HTMLInputElement).value;
                                }}
                            />
                        </div>
                    </div>
                    <div class="field">
                        <label class="field-label" for="add-user-pin">PIN</label>
                        <div class="field-control">
                            <input
                                id="add-user-pin"
                                class="field-input"
                                type=${this._pinVisible ? 'text' : 'password'}
                                inputmode="numeric"
                                .value=${this._pin}
                                @input=${(e: Event) => {
                                    this._pin = (e.target as HTMLInputElement).value;
                                }}
                            />
                            <ha-icon-button
                                class="lcm-reveal-button"
                                .path=${this._pinVisible ? mdiEyeOff : mdiEye}
                                .label=${this._pinVisible ? 'Hide PIN' : 'Show PIN'}
                                @click=${() => {
                                    this._pinVisible = !this._pinVisible;
                                }}
                            ></ha-icon-button>
                        </div>
                        <div class="field-generate">
                            <button
                                type="button"
                                class="generate-button"
                                .disabled=${this._generating}
                                @click=${this._generatePin}
                            >
                                <ha-svg-icon .path=${mdiDiceMultiple}></ha-svg-icon>
                                Generate PIN
                            </button>
                            <input
                                id="add-user-pin-length"
                                class="length-input"
                                type="number"
                                min=${MIN_PIN_LENGTH}
                                max=${MAX_PIN_LENGTH}
                                .value=${String(this._pinLength)}
                                @input=${(e: Event) => {
                                    this._pinLength = Number((e.target as HTMLInputElement).value);
                                }}
                            />
                            <label class="length-label" for="add-user-pin-length"> digits </label>
                        </div>
                    </div>
                    ${this._renderConditionField()}
                    <label class="dialog-check">
                        <input
                            type="checkbox"
                            .checked=${this._enabled}
                            @change=${(e: Event) => {
                                this._enabled = (e.target as HTMLInputElement).checked;
                            }}
                        />
                        <span>Enabled</span>
                    </label>
                    ${
                        this._error
                            ? html`<div class="dialog-error" aria-live="polite">
                                  ${this._error}
                              </div>`
                            : nothing
                    }
                    ${
                        this._saving
                            ? html`<div class="dialog-saving" aria-live="polite">Adding…</div>`
                            : nothing
                    }
                    <div class="dialog-actions">
                        <button class="dialog-action" @click=${this._close}>Cancel</button>
                        <button
                            class="dialog-action"
                            .disabled=${this._saving}
                            @click=${this._commit}
                        >
                            Add
                        </button>
                    </div>
                </div>
            </ha-dialog>
        `;
    }

    /**
     * The condition field, or nothing at all.
     *
     * Home Assistant does not always hand a dashboard its entity picker,
     * and there is no honest substitute -- an entity id typed from memory
     * is a support ticket. When the picker is missing the field is left
     * out and the user card's own condition dialog covers it, one step
     * later, with the picker it force-loads for itself.
     */
    private _renderConditionField(): TemplateResult | typeof nothing {
        if (!this._pickerReady) return nothing;
        return html`
            <div class="field">
                <span class="field-label">Active only when</span>
                <ha-entity-picker
                    .hass=${this.hass}
                    .value=${this._condition}
                    .includeDomains=${CONDITION_DOMAINS}
                    .entityFilter=${(state: { entity_id: string }) =>
                        isConditionEntity(state.entity_id)}
                    @value-changed=${(e: CustomEvent) => {
                        this._condition = (e.detail?.value as string) || '';
                    }}
                ></ha-entity-picker>
                <span class="field-help">
                    Optional. The PIN works only while this entity is on.
                </span>
            </div>
        `;
    }

    /**
     * Fill the PIN field from the `generate_pin` action.
     *
     * The action owns what "safe" means -- it rejects sequences, repeats
     * and the common-leak list, and draws from `secrets` -- so this asks
     * for a PIN rather than inventing one. The result is revealed: a code
     * you cannot read is one you cannot pass on.
     */
    private async _generatePin(): Promise<void> {
        if (!this.hass || this._generating) return;
        if (
            !Number.isInteger(this._pinLength) ||
            this._pinLength < MIN_PIN_LENGTH ||
            this._pinLength > MAX_PIN_LENGTH
        ) {
            this._error = `Length must be between ${MIN_PIN_LENGTH} and ${MAX_PIN_LENGTH}`;
            return;
        }
        this._generating = true;
        this._error = undefined;
        try {
            const result = await this.hass.callService(
                'lock_code_manager',
                'generate_pin',
                { length: this._pinLength },
                undefined,
                undefined,
                true
            );
            const pin = (result?.response as { pin?: string } | undefined)?.pin;
            if (!pin) {
                throw new Error('No PIN came back');
            }
            this._pin = pin;
            this._pinVisible = true;
        } catch (err) {
            this._error = `Could not generate a PIN: ${
                err instanceof Error ? err.message : String(err)
            }`;
        } finally {
            this._generating = false;
        }
    }

    private async _commit(): Promise<void> {
        const name = this._name.trim();
        if (!name) {
            this._error = 'Give the user a name';
            return;
        }
        if (!this.hass || !this._config) {
            this._error = 'Card not initialized';
            return;
        }
        if (this._saving) return;
        this._saving = true;
        this._error = undefined;
        try {
            await this.hass.callService('lock_code_manager', 'add_user', {
                // Either/or, never both: the action treats the two as
                // exclusive and refuses a call that carries the pair.
                ...(this._config.config_entry_id
                    ? { config_entry_id: this._config.config_entry_id }
                    : { config_entry_title: this._config.config_entry_title }),
                // The list shape the action declares. The flat one still works,
                // through a shim kept for calls written before 6.0 -- but the
                // shipped card should not be the thing keeping that shim alive.
                users: [
                    {
                        enabled: this._enabled,
                        name,
                        ...(this._pin && { pin: this._pin }),
                        ...(this._condition && { condition: this._condition })
                    }
                ]
            });
        } catch (err) {
            this._error = err instanceof Error ? err.message : String(err);
            return;
        } finally {
            this._saving = false;
        }
        // The dashboard is generated by a strategy, so the new user has no
        // card until the strategy runs again. Nothing short of a reload
        // re-runs it.
        this._reload();
    }
}

